int LLVMFuzzerTestOneInput(const uint8_t *src, size_t size)
{

    uint32_t seed = FUZZ_seed(&src, &size);
    int i;
    if (!dctx) {
        dctx = ZSTD_createDCtx();
        FUZZ_ASSERT(dctx);
    }
    /* Run it 10 times over 10 output sizes. Reuse the context. */
    for (i = 0; i < 10; ++i) {
